<?php
require_once 'auth.php'; require_role(['super_admin']); require_once 'db.php';
require_once 'result_document.php';
$message='';$type='error';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try {

 if(!verify_csrf())$message='Invalid request.';else{
  $action=$_POST['action']??'settings';
  if($action==='password'){
   $current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$username=$_SESSION['admin_username']??'';
   $st=mysqli_prepare($conn,'SELECT password FROM admin WHERE username=? LIMIT 1');mysqli_stmt_bind_param($st,'s',$username);mysqli_stmt_execute($st);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($st));
   if(!$r||!password_verify($current,$r['password']))$message='Current password is incorrect.';elseif(!valid_admin_password($new))$message='Use 12-72 characters including uppercase, lowercase and a number.';elseif($new!==$confirm)$message='New passwords do not match.';else{$hash=password_hash($new,PASSWORD_DEFAULT);$u=mysqli_prepare($conn,'UPDATE admin SET password=? WHERE username=?');mysqli_stmt_bind_param($u,'ss',$hash,$username);mysqli_stmt_execute($u);audit_log($conn,'PASSWORD','admin',$username,'Admin password changed');$message='Password changed successfully.';$type='success';}
  }else{
   $base=is_string($_POST['portal_base_url']??null)?trim($_POST['portal_base_url']):'';
   $parsed=parse_url($base);
   if($base!=='' && (strlen($base)>140 || !filter_var($base,FILTER_VALIDATE_URL) || !in_array(strtolower($parsed['scheme']??''),['http','https'],true) || isset($parsed['user']) || isset($parsed['pass']) || isset($parsed['query']) || isset($parsed['fragment']))){$message='Enter a valid HTTP/HTTPS portal URL (maximum 140 characters), without a query or fragment.';}else{
   $keys=['portal_base_url','system_name','university_name','faculty_name','faculty_website','registrar_name','registrar_title','default_result_status','login_max_attempts','login_lock_minutes','session_timeout_minutes','maintenance_mode','system_version'];
   foreach($keys as $k){$v=trim($_POST[$k]??'');if($k==='default_result_status')$v='draft';$st=mysqli_prepare($conn,'INSERT INTO system_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');mysqli_stmt_bind_param($st,'ss',$k,$v);mysqli_stmt_execute($st);}audit_log($conn,'UPDATE','settings','system','System settings updated');$message='System settings saved.';$type='success';}
  }
 }

 } catch(mysqli_sql_exception $ex) { mysqli_rollback($conn); $message='This change could not be saved. The record may be locked, protected or changed by another user. Refresh and try again.'; $type='error'; }
}
$defaults=['portal_base_url'=>'','system_name'=>'Student Result Management System','university_name'=>'South Eastern University of Sri Lanka','faculty_name'=>'Faculty of Applied Sciences','faculty_website'=>'https://www.seu.ac.lk/fas/','registrar_name'=>'MACM Rameez','registrar_title'=>'Deputy Registrar/Examination','default_result_status'=>'draft','login_max_attempts'=>'5','login_lock_minutes'=>'15','session_timeout_minutes'=>'30','maintenance_mode'=>'0','system_version'=>'v1.0'];foreach($defaults as $k=>$v)$settings[$k]=app_setting($conn,$k,$v);
?>
